estilos.css_firma:
:root{--base:#0f1b2d;--prim:#1a3d6b;--acento:#e8a33d;--apoyo:#2fa88f;--tinta:#152238;--gris:#5b6478;--linea:#e4e7ec;--papel:#f6f7f9;--ok:#0d7a5f;--err:#c0392b;--disp:"Barlow Condensed","Arial Narrow",sans-serif;--mono:ui-monospace,Consolas,monospace;--sombra:0 1px 2px rgba(15,27,45,.06),0 10px 28px -14px rgba(15,27,45,.28)}
body{margin:0;background:#eef1f5;color:#152238;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:14px;line-height:1.45}
.enc{background:var(--base);color:#fff;height:62px;display:flex;align-items:center;justify-content:space-between;padding:0 24px}
.enc .gremio i{display:block;width:4px;height:30px;background:var(--acento);border-radius:2px}
.tab{font-family:var(--disp);font-size:13px;letter-spacing:.8px;text-transform:uppercase;color:#c9d3e3;padding:8px 12px;border:1px solid #2a3b55;border-radius:9px;background:#152238}
.tab.act{background:#fff;color:var(--base);border-color:#fff}
.franja{background:linear-gradient(180deg,var(--base) 0,rgba(15,27,45,0) 220px)}
h1{font-family:var(--disp);font-weight:700;font-size:31px;line-height:1;letter-spacing:.3px;text-transform:uppercase;color:#fff}
.hoja{display:grid;grid-template-columns:184px minmax(0,1fr) 300px;gap:20px;align-items:start}
.riel .paso.act{background:#fff;box-shadow:var(--sombra)}
.riel .num{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;background:#fff;border:1.5px solid #c8d0db;color:var(--gris)}
.riel .paso.hecho .num{background:var(--ok);border-color:var(--ok);color:#fff}
.riel .paso.act .num{background:var(--prim);border-color:var(--prim);color:#fff}
.sheet{background:#fff;border-radius:12px;box-shadow:var(--sombra)}
.area{background:repeating-linear-gradient(0deg,rgba(26,61,107,.05) 0 1px,transparent 1px 24px),repeating-linear-gradient(90deg,rgba(26,61,107,.05) 0 1px,transparent 1px 24px);border:1px solid #d6dce5;border-radius:12px;padding:20px}
.fila{display:grid;grid-template-columns:16px 28px minmax(0,1fr) 88px 142px 86px 62px;align-items:center;gap:8px;padding:9px 10px;border-top:1px solid var(--linea);font-size:13px}
.fila.cab{background:var(--papel);font-size:11px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;color:#4b5567}
.fila .n{font-family:var(--mono);font-size:12px;color:var(--prim);font-weight:700}
.radios{display:flex;gap:4px;background:#eef1f5;padding:3px;border-radius:9px}
.radios label.on{background:#fff;color:var(--tinta);font-weight:600;box-shadow:0 1px 2px rgba(15,27,45,.12)}
.sw b.on{background:var(--err);color:#fff}
.btn.pri{background:var(--acento);color:var(--base)}
.phone{background:var(--base);border-radius:22px;padding:14px;box-shadow:0 1px 0 rgba(255,255,255,.12) inset,0 14px 36px -16px rgba(15,27,45,.55);border:1px solid rgba(255,255,255,.14)}
.sello{position:absolute;transform:rotate(-8deg);border:2px solid var(--ok);color:var(--ok);font-family:var(--disp);font-size:15px;letter-spacing:1.5px;padding:2px 8px;border-radius:4px;background:rgba(255,255,255,.9)}

