@keyframes sello{from{opacity:0;transform:rotate(-8deg) scale(1.4)}to{opacity:1;transform:rotate(-8deg) scale(1)}}
.o2 .cara{background:#fff;border:1px solid var(--linea);border-radius:12px;padding:14px 16px 14px 22px;position:relative;overflow:hidden}
.o2 .cara::before{content:"";position:absolute;left:0;top:0;bottom:0;width:10px;background:var(--marca-base)}
.o2 .cara::after{content:attr(data-n);position:absolute;left:0;top:0;bottom:0;width:10px;display:flex;align-items:center;justify-content:center;writing-mode:vertical-rl;transform:rotate(180deg);font-family:var(--mono);font-size:7px;color:rgba(255,255,255,.75);letter-spacing:1.2px}
.o2 .cara h1{font-family:var(--disp);font-weight:700;font-size:26px;line-height:1;text-transform:uppercase;letter-spacing:.5px}
.o2 .cara .meta{font-family:var(--mono);font-size:10px;color:var(--gris);letter-spacing:.3px}
.o2 .sello{position:absolute;right:14px;top:12px;border:2.5px solid var(--marca-acento);color:var(--marca-acento);font-family:var(--disp);font-weight:700;font-size:15px;letter-spacing:2px;text-transform:uppercase;padding:3px 9px;border-radius:5px;transform:rotate(-8deg);animation:sello .5s .3s ease both;opacity:0;mix-blend-mode:multiply}
.o2 .pest span{padding:7px 13px 6px;border:1px solid var(--linea);border-bottom:none;border-radius:9px 9px 0 0;font-size:12px;font-weight:600;color:var(--gris);background:#eef0f3}
.o2 .pest span.act{background:#fff;color:var(--tinta);position:relative;top:1px;border-top:3px solid var(--marca-acento)}
.o2 .hoja{background:#fff;border:1px solid var(--linea);border-radius:0 0 12px 12px;padding:6px 12px 12px}
.o2 .f{position:relative;border:1px solid var(--linea);border-radius:8px;padding:9px 11px 9px 18px;background:linear-gradient(160deg,#fff,var(--papel))}
.o2 .f::before{content:"";position:absolute;left:8px;top:6px;bottom:6px;border-left:2px dotted var(--linea)}
.o2 .f.nl::before{border-left-color:var(--marca-acento)}
.o2 .f .de{font-family:var(--mono);font-size:9.5px;color:var(--gris);display:flex;justify-content:space-between}
.o2 .nuevo{position:absolute;right:9px;top:8px;border:1.5px solid var(--marca-acento);color:var(--marca-acento);font-family:var(--disp);font-size:10px;letter-spacing:1.5px;padding:0 5px;border-radius:3px;transform:rotate(-6deg)}
.o2 .kv{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px dashed var(--linea);padding-top:10px}
.o2 .kv b{display:block;font-family:var(--disp);font-size:24px;line-height:1}
.o2 .ficha-b .lin{flex:1;border-bottom:1.5px solid var(--tinta);font-family:var(--mono);font-size:12.5px;color:#98a2b3}
.o2 .carp .lab{position:absolute;top:-11px;left:12px;font-family:var(--disp);font-size:11px;letter-spacing:1.4px;text-transform:uppercase;padding:2px 9px;border-radius:6px 6px 0 0;font-weight:700}
.o2 .sello.est{border-color:currentColor;font-size:12.5px;right:12px;bottom:12px;letter-spacing:1.4px;animation:none;opacity:.95;transform:rotate(-5deg)}
.e-ini{background:#fdf3e7;color:#8a5a1a}.e-tra{background:#e8def5;color:#5b3d8a}.e-res{background:#e3f2ee;color:#0d7a5f}.e-esp{background:#f8e5e2;color:#b23a2e}

@keyframes entra{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.o3 .top3{background:var(--marca-base);padding:0 15px 12px;color:#fff;position:relative;overflow:hidden}
.o3 .top3 h1{font-family:var(--disp);font-weight:700;font-size:30px;line-height:1;text-transform:uppercase;letter-spacing:.5px}
.o3 .chip{border:1px solid rgba(255,255,255,.18);border-radius:20px;padding:5px 12px;font-size:12px;font-weight:600;color:rgba(255,255,255,.75)}
.o3 .chip.act{background:var(--marca-acento);color:var(--marca-base);border-color:var(--marca-acento)}
.o3 .chip i{font-style:normal;font-family:var(--mono);font-size:10.5px;opacity:.75}
.o3 .hilo{padding:6px 15px 90px;position:relative}
.o3 .hilo::before{content:"";position:absolute;left:31px;top:0;bottom:60px;width:2px;background:var(--linea)}
.o3 .hito i svg{width:18px;height:18px;fill:var(--papel);stroke:var(--gris);stroke-width:1.6}
.o3 .hito span{font-family:var(--disp);font-size:13px;letter-spacing:1.6px;text-transform:uppercase;color:var(--gris)}
.o3 .m .avatar{width:32px;height:32px;box-shadow:0 0 0 3px var(--papel);position:relative}
.o3 .m.nl .avatar::after{content:"";position:absolute;right:-2px;bottom:-2px;width:11px;height:11px;border-radius:50%;background:var(--marca-acento);border:2px solid var(--papel);animation:pulso 1.8s ease-out infinite}
.o3 .bur{flex:1;background:#fff;border:1px solid var(--linea);border-radius:4px 14px 14px 14px;padding:9px 12px 10px}
.o3 .m.nl .bur{border-color:color-mix(in srgb,var(--marca-acento) 50%,var(--linea));background:color-mix(in srgb,var(--marca-acento) 5%,#fff)}
.o3 .bur .tx{font-size:12.5px;color:var(--gris);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.o3 .aten{background:linear-gradient(150deg,var(--marca-base),color-mix(in srgb,var(--marca-primario) 55%,var(--marca-base)));color:#fff;border-radius:14px;padding:13px 14px;border-left:5px solid var(--marca-acento);animation:entra .5s ease both}
.o3 .aten .k{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;color:var(--marca-acento);font-weight:700}
.o3 .aten .tit{font-family:var(--disp);font-size:20px;line-height:1.05;text-transform:uppercase}
.o3 .aten .msg{display:flex;gap:8px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:8px 10px}
.o3 .aten .bts span.cta{background:var(--marca-acento);border-color:var(--marca-acento);color:var(--marca-base)}
.o3 .acc{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.o3 .acc div{border-radius:12px;padding:12px;border:1px solid var(--linea);background:#fff}
.o3 .acc div.cta{background:var(--marca-acento);border-color:var(--marca-acento);color:var(--marca-base)}
.o3 .fil span.act{background:var(--marca-base);border-color:var(--marca-base);color:#fff}
.o3 .barra-p{display:flex;gap:3px}.o3 .barra-p i{flex:1;height:4px;border-radius:2px;background:var(--linea)}
.o3 .barra-p i.on{background:var(--marca-primario)}.o3 .barra-p i.cur{background:var(--marca-acento)}.o3 .barra-p i.al{background:#b23a2e}
